import React from 'react';

const TABS = [
  {
    id: 'history', label: 'Log',
    icon: <svg viewBox="0 0 24 24" fill="none" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></svg>,
  },
  {
    id: 'checkin', label: 'Day',
    icon: <svg viewBox="0 0 24 24" fill="none" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="9"/><path d="M8 12l3 3 5-5"/></svg>,
  },
  {
    id: 'home', label: 'Home',
    icon: <svg viewBox="0 0 24 24" fill="none" strokeLinecap="round" strokeLinejoin="round"><path d="M3 12L12 4l9 8"/><path d="M5 10v9h4v-4h4v4h5v-9"/></svg>,
  },
  {
    id: 'breathing', label: 'Breathe',
    icon: <svg viewBox="0 0 24 24" fill="none" strokeLinecap="round" strokeLinejoin="round"><path d="M12 4c0 0-4 3-4 7s4 5 4 9"/><path d="M12 4c0 0 4 3 4 7s-4 5-4 9"/></svg>,
  },
];

export default function Nav({ page, setPage }) {
  return (
    <div style={{
      position: 'fixed',
      bottom: 32,
      left: '50%',
      transform: 'translateX(-50%)',
      zIndex: 300,
      display: 'flex',
      alignItems: 'flex-end',
      gap: 16,
    }}>
      {TABS.map(tab => {
        const active = page === tab.id;
        const size = active ? 60 : 48;
        return (
          <div key={tab.id} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6 }}>
            <button
              onClick={() => setPage(tab.id)}
              aria-label={tab.label}
              style={{
                width: size,
                height: size,
                borderRadius: '50%',
                border: 'none',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                background: active ? '#7EC8C8' : 'rgba(255,255,255,0.08)',
                boxShadow: active
                  ? '0 1px 0 rgba(255,255,255,0.4) inset, 0 -1px 0 rgba(0,0,0,0.12) inset, 0 0 0 1px rgba(126,200,200,0.4), 0 4px 20px rgba(45,107,107,0.45)'
                  : '0 0 0 1px rgba(255,255,255,0.09)',
                transition: 'all 0.3s cubic-bezier(0.34,1.3,0.64,1)',
                WebkitTapHighlightColor: 'transparent',
              }}
            >
              <svg
                viewBox="0 0 24 24"
                width={active ? 22 : 18}
                height={active ? 22 : 18}
                fill="none"
                stroke={active ? '#0F1C1C' : 'rgba(255,255,255,0.35)'}
                strokeWidth={active ? 2.2 : 1.8}
                strokeLinecap="round"
                strokeLinejoin="round"
                style={{ transition: 'all 0.3s' }}
              >
                {tab.icon.props.children}
              </svg>
            </button>
            <span style={{
              fontSize: 9,
              fontWeight: 700,
              letterSpacing: '0.08em',
              textTransform: 'uppercase',
              color: active ? 'rgba(238,234,227,0.65)' : 'rgba(238,234,227,0.2)',
              transition: 'color 0.25s',
              fontFamily: "'Inter', sans-serif",
              whiteSpace: 'nowrap',
            }}>
              {tab.label}
            </span>
          </div>
        );
      })}
    </div>
  );
}
